css:
.canvas{--gel:#5fcab8;--gel-text:#075e54;--gel-night:#a7ebe1;--coolant:#5fcab8;--coolant-text:#075e54;--coolant-night:#a7ebe1;--flare:#ff9f84;--flare-text:#97301a;--flare-night:#ffb4a0;--sodium:#f0bd52;--sodium-text:#6c4a00;--sodium-night:#ffd88a;--rule:rgba(23,32,49,.34);--guide:rgba(23,32,49,.15);--plate-rule:rgba(231,237,240,.32);--plate-guide:rgba(231,237,240,.13);--card-radius:calc(14px * var(--s));--control-radius:calc(10px * var(--s))}
.tone-accent::before{content:"";position:absolute;left:0;right:0;top:0;height:calc(12px * var(--s));background:var(--gel)}
.gel-disc{display:inline-block;width:.62em;height:.62em;border-radius:50%;background:var(--gel);vertical-align:.04em;margin-right:.32em;border:calc(2px * var(--s)) solid var(--ink);box-sizing:border-box}
